mapper.select:
SELECT EXISTS(
  SELECT 1 FROM registration_verification_token
  WHERE token_hash = #{tokenHash} AND exchange_session_hash = #{exchangeSessionHash}
    AND exchanged_at IS NOT NULL AND consumed_at IS NULL AND expires_at > UTC_TIMESTAMP()
)

SELECT COUNT(*) FROM registration_verification_token
WHERE user_id = #{userId}
  AND created_at > DATE_SUB(UTC_TIMESTAMP(), INTERVAL #{withinSeconds} SECOND)
